/// <summary>
/// Example UPSPricingAttribute of table <c>RetailInventTable</c> field keyingInPrice.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeRetailInventTableKeyingInPrice extends UPSPricingAttributeRetailInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(RetailInventTable, keyingInPrice);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::Enum);
    RetailInventTable retailInventTable;
    while select keyingInPrice from retailInventTable
        group by keyingInPrice
    {
        ret.add(retailInventTable.keyingInPrice);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(RetailInventTable, keyingInPrice));
    qbr.value(queryValue(_value));
}
